import React, { Component } from "react";
import Typical from "react-typical";
import Switch from "react-switch";

class Header extends Component {
  titles = [];

  constructor() {
    super();
    this.state = { checked: false };
    this.onThemeSwitchChange = this.onThemeSwitchChange.bind(this);
  }

  onThemeSwitchChange(checked) {
    this.setState({ checked });
    this.setTheme();
  }

  setTheme() {
    var dataThemeAttribute = "data-theme";
    var body = document.body;
    var newTheme =
      body.getAttribute(dataThemeAttribute) === "dark" ? "light" : "dark";
    body.setAttribute(dataThemeAttribute, newTheme);
  }

  render() {
    if (this.props.sharedData) {
      var name = this.props.sharedData.name;
      // Get titles based on current language
      const titleIndex = this.props.language === 'en' ? 0 : 1;
      const currentTitle = this.props.sharedData.titles[titleIndex];
      this.titles = [currentTitle.toUpperCase(), 1500];
    }

    const HeaderTitleTypeAnimation = React.memo( () => {
      return <Typical className="title-styles" steps={this.titles} loop={50} />
    }, (props, prevProp) => true);

    const iconStyle = {
      display: "flex",
      justifyContent: "center",
      alignItems: "center",
      height: "100%",
      fontSize: "25px",
      paddingRight: "5px",
      color: "#353239",
      width: "100%"
    };

    return (
      <header id="home" style={{ height: window.innerHeight - 140, display: 'block' }}>
        <div className="row aligner" style={{height: '100%'}}>
          <div className="col-md-12">
            <div>
              <span className="iconify header-icon" data-icon="la:laptop-code" data-inline="false"></span>
              <br/>
              <h1 className="mb-0">
                <Typical steps={[name]} wrapper="p" />
              </h1>
              <div className="title-container">
                <HeaderTitleTypeAnimation />
              </div>
              <Switch
                checked={this.state.checked}
                onChange={this.onThemeSwitchChange}
                offColor="#baaa80"
                onColor="#353535"
                className="react-switch mx-auto"
                width={90}
                height={40}
                uncheckedIcon={
                  <iconify-icon
                    icon="twemoji:sun"
                    style={iconStyle}
                  ></iconify-icon>
                }
                checkedIcon={
                  <iconify-icon
                    icon="twemoji:crescent-moon"
                    style={iconStyle}
                  ></iconify-icon>
                }
                id="icon-switch"
              />
              <div className="language-switch">
                <button 
                  className={`language-btn ${this.props.language === 'en' ? 'active' : ''}`} 
                  onClick={this.props.toggleLanguage}
                  title="English"
                >
                  <span style={{ fontSize: '14px', fontWeight: 'bold' }}>EN</span>
                </button>
                <button 
                  className={`language-btn ${this.props.language === 'it' ? 'active' : ''}`} 
                  onClick={this.props.toggleLanguage}
                  title="Italian"
                >
                  <span style={{ fontSize: '14px', fontWeight: 'bold' }}>IT</span>
                </button>
              </div>
            </div>
          </div>
        </div>
      </header>
    );
  }
}

export default Header;
